Here is the commit message:
xfs: fix log recovery buffer allocation for the legacy h_size
 fixup

Commit a70f9fe52daa ("xfs: detect and handle invalid iclog size set by
mkfs") added a fixup for incorrect h_size values used for the initial
umount record in old xfsprogs versions.  Later commit 0c771b99d6c9
("xfs: clean up calculation of LR header blocks") cleaned up the log
reover buffer calculation, but stoped using the fixed up h_size value
to size the log recovery buffer, which can lead to an out of bounds
access when the incorrect h_size does not come from the old mkfs
tool, but a fuzzer.

Fix this by open coding xlog_logrec_hblks and taking the fixed h_size
into account for this calculation.

Fixes: 0c771b99d6c9 ("xfs: clean up calculation of LR header blocks")
Reported-by: Sam Sun <samsun1006219@gmail.com>
Signed-off-by: Christoph Hellwig <hch@lst.de>
Reviewed-by: Brian Foster <bfoster@redhat.com>
Reviewed-by: "Darrick J. Wong" <djwong@kernel.org>
Signed-off-by: Chandan Babu R <chandanbabu@kernel.org>

Here is the root cause:
The bug was caused by the failure to use the corrected header size (`h_size`) when calculating the number of header blocks (`hblks`) for log recovery buffer allocation. This oversight could lead to an out-of-bounds access if the `h_size` was incorrectly set, particularly when it originated from a fuzzer or an old version of the `mkfs` tool that did not properly set the header size.

Here is the patch:
  */
 STATIC int
 xlog_do_recovery_pass(
 	struct xlog		*log,
 	xfs_daddr_t		head_blk,
 	xfs_daddr_t		tail_blk,
 	int			pass,
 	xfs_daddr_t		*first_bad)	/* out: first bad log rec */
 {
 	xlog_rec_header_t	*rhead;
 	xfs_daddr_t		blk_no, rblk_no;
 	xfs_daddr_t		rhead_blk;
 	char			*offset;
 	char			*hbp, *dbp;
 	int			error = 0, h_size, h_len;
 	int			error2 = 0;
 	int			bblks, split_bblks;
-	int			hblks, split_hblks, wrapped_hblks;
+	int			hblks = 1, split_hblks, wrapped_hblks;
 	int			i;
 	struct hlist_head	rhash[XLOG_RHASH_SIZE];
 	LIST_HEAD		(buffer_list);

 	ASSERT(head_blk != tail_blk);
 	blk_no = rhead_blk = tail_blk;

 	for (i = 0; i < XLOG_RHASH_SIZE; i++)
 		INIT_HLIST_HEAD(&rhash[i]);

 	/*
 	 * Read the header of the tail block and get the iclog buffer size from
 	 * h_size.  Use this to tell how many sectors make up the log header.
 	 */
 	if (xfs_has_logv2(log->l_mp)) {
 		/*
 		 * When using variable length iclogs, read first sector of
 		 * iclog header and extract the header size from it.  Get a
 		 * new hbp that is the correct size.
 		 */
 		hbp = xlog_alloc_buffer(log, 1);
 		if (!hbp)
 			return -ENOMEM;

 		error = xlog_bread(log, tail_blk, 1, hbp, &offset);
 		if (error)
 			goto bread_err1;

 		rhead = (xlog_rec_header_t *)offset;

 		/*
 		 * xfsprogs has a bug where record length is based on lsunit but
 		 * h_size (iclog size) is hardcoded to 32k. Now that we
 		 * unconditionally CRC verify the unmount record, this means the
 		 * log buffer can be too small for the record and cause an
 		 * overrun.
 		 *
 		 * Detect this condition here. Use lsunit for the buffer size as
 		 * long as this looks like the mkfs case. Otherwise, return an
 		 * error to avoid a buffer overrun.
 		 */
 		h_size = be32_to_cpu(rhead->h_size);
 		h_len = be32_to_cpu(rhead->h_len);
 		if (h_len > h_size && h_len <= log->l_mp->m_logbsize &&
 		    rhead->h_num_logops == cpu_to_be32(1)) {
 			xfs_warn(log->l_mp,
 		"invalid iclog size (%d bytes), using lsunit (%d bytes)",
 				 h_size, log->l_mp->m_logbsize);
 			h_size = log->l_mp->m_logbsize;
 		}

 		error = xlog_valid_rec_header(log, rhead, tail_blk, h_size);
 		if (error)
 			goto bread_err1;

-		hblks = xlog_logrec_hblks(log, rhead);
-		if (hblks != 1) {
-			kvfree(hbp);
-			hbp = xlog_alloc_buffer(log, hblks);
+		/*
+		 * This open codes xlog_logrec_hblks so that we can reuse the
+		 * fixed up h_size value calculated above.  Without that we'd
+		 * still allocate the buffer based on the incorrect on-disk
+		 * size.
+		 */
+		if (h_size > XLOG_HEADER_CYCLE_SIZE &&
+		    (rhead->h_version & cpu_to_be32(XLOG_VERSION_2))) {
+			hblks = DIV_ROUND_UP(h_size, XLOG_HEADER_CYCLE_SIZE);
+			if (hblks > 1) {
+				kvfree(hbp);
+				hbp = xlog_alloc_buffer(log, hblks);
+			}
 		}
 	} else {
 		ASSERT(log->l_sectBBsize == 1);
-		hblks = 1;
 		hbp = xlog_alloc_buffer(log, 1);
 		h_size = XLOG_BIG_RECORD_BSIZE;
 	}

 	if (!hbp)
 		return -ENOMEM;
 	dbp = xlog_alloc_buffer(log, BTOBB(h_size));
 	if (!dbp) {
 		kvfree(hbp);
 		return -ENOMEM;
 	}

 	memset(rhash, 0, sizeof(rhash));
 	if (tail_blk > head_blk) {
 		/*
 		 * Perform recovery around the end of the physical log.
 		 * When the head is not on the same cycle number as the tail,
 		 * we can't do a sequential recovery.
 		 */
 		while (blk_no < log->l_logBBsize) {
 			/*
 			 * Check for header wrapping around physical end-of-log
 			 */
 			offset = hbp;
 			split_hblks = 0;
 			wrapped_hblks = 0;
 			if (blk_no + hblks <= log->l_logBBsize) {
 				/* Read header in one read */
 				error = xlog_bread(log, blk_no, hblks, hbp,
 						   &offset);
 				if (error)
 					goto bread_err2;
 			} else {
 				/* This LR is split across physical log end */
 				if (blk_no != log->l_logBBsize) {
 					/* some data before physical log end */
 					ASSERT(blk_no <= INT_MAX);
 					split_hblks = log->l_logBBsize - (int)blk_no;
 					ASSERT(split_hblks > 0);
 					error = xlog_bread(log, blk_no,
 							   split_hblks, hbp,
 							   &offset);
 					if (error)
 						goto bread_err2;
 				}

 				/*
 				 * Note: this black magic still works with
 				 * large sector sizes (non-512) only because:
 				 * - we increased the buffer size originally
 				 *   by 1 sector giving us enough extra space
 				 *   for the second read;
 				 * - the log start is guaranteed to be sector
 				 *   aligned;
 				 * - we read the log end (LR header start)
 				 *   _first_, then the log start (LR header end)
 				 *   - order is important.
 				 */
 				wrapped_hblks = hblks - split_hblks;
 				error = xlog_bread_noalign(log, 0,
 						wrapped_hblks,
 						offset + BBTOB(split_hblks));
 				if (error)
 					goto bread_err2;
 			}
 			rhead = (xlog_rec_header_t *)offset;
 			error = xlog_valid_rec_header(log, rhead,
 					split_hblks ? blk_no : 0, h_size);
 			if (error)
 				goto bread_err2;

 			bblks = (int)BTOBB(be32_to_cpu(rhead->h_len));
 			blk_no += hblks;

 			/*
 			 * Read the log record data in multiple reads if it
 			 * wraps around the end of the log. Note that if the
 			 * header already wrapped, blk_no could point past the
 			 * end of the log. The record data is contiguous in
 			 * that case.
 			 */
 			if (blk_no + bblks <= log->l_logBBsize ||
 			    blk_no >= log->l_logBBsize) {
 				rblk_no = xlog_wrap_logbno(log, blk_no);
 				error = xlog_bread(log, rblk_no, bblks, dbp,
 						   &offset);
 				if (error)
 					goto bread_err2;
 			} else {
 				/* This log record is split across the
 				 * physical end of log */
 				offset = dbp;
 				split_bblks = 0;
 				if (blk_no != log->l_logBBsize) {
 					/* some data is before the physical
 					 * end of log */
 					ASSERT(!wrapped_hblks);
 					ASSERT(blk_no <= INT_MAX);
 					split_bblks =
 						log->l_logBBsize - (int)blk_no;
 					ASSERT(split_bblks > 0);
 					error = xlog_bread(log, blk_no,
 							split_bblks, dbp,
 							&offset);
 					if (error)
 						goto bread_err2;
 				}

 				/*
 				 * Note: this black magic still works with
 				 * large sector sizes (non-512) only because:
 				 * - we increased the buffer size originally
 				 *   by 1 sector giving us enough extra space
 				 *   for the second read;
 				 * - the log start is guaranteed to be sector
 				 *   aligned;
 				 * - we read the log end (LR header start)
 				 *   _first_, then the log start (LR header end)
 				 *   - order is important.
 				 */
 				error = xlog_bread_noalign(log, 0,
 						bblks - split_bblks,
 						offset + BBTOB(split_bblks));
 				if (error)
 					goto bread_err2;
 			}

 			error = xlog_recover_process(log, rhash, rhead, offset,
 						     pass, &buffer_list);
 			if (error)
 				goto bread_err2;

 			blk_no += bblks;
 			rhead_blk = blk_no;
 		}

 		ASSERT(blk_no >= log->l_logBBsize);
 		blk_no -= log->l_logBBsize;
 		rhead_blk = blk_no;
 	}

 	/* read first part of physical log */
 	while (blk_no < head_blk) {
 		error = xlog_bread(log, blk_no, hblks, hbp, &offset);
 		if (error)
 			goto bread_err2;

 		rhead = (xlog_rec_header_t *)offset;
 		error = xlog_valid_rec_header(log, rhead, blk_no, h_size);
 		if (error)
 			goto bread_err2;

 		/* blocks in data section */
 		bblks = (int)BTOBB(be32_to_cpu(rhead->h_len));
 		error = xlog_bread(log, blk_no+hblks, bblks, dbp,
 				   &offset);
 		if (error)
 			goto bread_err2;

 		error = xlog_recover_process(log, rhash, rhead, offset, pass,
 					     &buffer_list);
 		if (error)
 			goto bread_err2;

 		blk_no += bblks + hblks;
 		rhead_blk = blk_no;
 	}

  bread_err2:
 	kvfree(dbp);
  bread_err1:
 	kvfree(hbp);

 	/*
 	 * Submit buffers that have been dirtied by the last record recovered.
 	 */
 	if (!list_empty(&buffer_list)) {
 		if (error) {
 			/*
 			 * If there has been an item recovery error then we
 			 * cannot allow partial checkpoint writeback to
 			 * occur.  We might have multiple checkpoints with the
 			 * same start LSN in this buffer list, and partial
 			 * writeback of a checkpoint in this situation can
 			 * prevent future recovery of all the changes in the
 			 * checkpoints at this start LSN.
 			 *
 			 * Note: Shutting down the filesystem will result in the
 			 * delwri submission marking all the buffers stale,
 			 * completing them and cleaning up _XBF_LOGRECOVERY
 			 * state without doing any IO.
 			 */
 			xlog_force_shutdown(log, SHUTDOWN_LOG_IO_ERROR);
 		}
 		error2 = xfs_buf_delwri_submit(&buffer_list);
 	}

 	if (error && first_bad)
 		*first_bad = rhead_blk;

 	/*
 	 * Transactions are freed at commit time but transactions without commit
 	 * records on disk are never committed. Free any that may be left in the
 	 * hash table.
 	 */
 	for (i = 0; i < XLOG_RHASH_SIZE; i++) {
 		struct hlist_node	*tmp;
 		struct xlog_recover	*trans;

 		hlist_for_each_entry_safe(trans, tmp, &rhash[i], r_list)
 			xlog_recover_free_trans(trans);
 	}

 	return error ? error : error2;
 }



